import CoreGraphics
import BetterTileCore
import Foundation
import ImageIO
import os

/// Pre-rendered glyph artwork, generated by the test-only reference renderer
/// and bundled as PNGs. Wheel sets already contain their final,
/// appearance-resolved ink; callers must not retint them. menuGlass alone
/// supplies black template coverage and must be wrapped as an AppKit
/// template image. See docs/ARCHITECTURE.md, "Layout Wheel glyph masks".
public enum GlyphMaskStore {
    public enum Set: String, Sendable { case wheel, wheelSymbols, wheelLabels; case menuGlass = "menu-glass" }
    public enum Appearance: String, Codable, Sendable { case light, dark }

    struct Entry: Codable, Equatable {
        let file: String
        let width: Int
        let height: Int
        /// Per-appearance RGBA PNGs preserve final sRGB ink and alpha.
        let format: String
    }

    struct Manifest: Codable {
        let version: Int
        let platform: [String: String]
        let sources: [String: String]
        let entries: [String: Entry]
        let symbolInkSizes: [String: [Double]]
        let findings: [String: Int]
    }

    static func key(set: Set, id: String, pointSize: Double, scale: Double, appearance: Appearance) -> String {
        "\(set.rawValue)|\(id)|\(String(pointSize.bitPattern, radix: 16))|\(scale)|\(appearance.rawValue)"
    }

    @MainActor static func wheelID(_ slot: LayoutWheelSlot) -> String {
        if let glyph = slot.glyph?.canonical {
            switch glyph {
            case .layout(let preset): return "layout:\(preset.rawValue)"
            case .mode(let mode): return "mode:\(mode.rawValue)"
            case .layouts: return "layouts"
            }
        }
        if let action = slot.windowAction, WindowActionPartitionGlyph.actions[action] != nil {
            return "action:\(action.rawValue)"
        }
        return "symbol:\(slot.symbolName)"
    }

    @MainActor private static var cache = LayoutWheelLiquidImageCache(limit: 1_048_576)
    @MainActor private static var reportedMissingKeys: Swift.Set<String> = []
    private static let logger = Logger(subsystem: "com.lmckarma.BetterTile", category: "GlyphMaskStore")

    private static let manifest: Manifest? = {
        guard let directory = resourceDirectory else {
            reportUnavailable("The GlyphMasks folder is missing from \(Bundle.module.bundlePath).")
            return nil
        }
        do {
            let data = try Data(contentsOf: directory.appendingPathComponent("manifest.json"))
            return try JSONDecoder().decode(Manifest.self, from: data)
        } catch {
            reportUnavailable("The glyph mask manifest cannot be read: \(error)")
            return nil
        }
    }()

    /// The `.copy` resource folder in this target's SwiftPM resource bundle.
    /// `Bundle.module` finds the bundle in every build layout: `swift test`
    /// under each SwiftPM version, and the Xcode app, which embeds it in
    /// Contents/Resources. If the bundle itself is absent, the generated
    /// accessor stops the process; a build cannot ship without it.
    static var resourceDirectory: URL? {
        Bundle.module.url(forResource: "GlyphMasks", withExtension: nil)
    }

    /// Missing bundled artwork is a packaging fault, never an expected state.
    /// Debug stops at once; Release logs a fault, and the caller's existing
    /// fallback runs (the panel wheel, or the action's SF Symbol).
    private static func reportUnavailable(_ message: String) {
        logger.fault("\(message, privacy: .public)")
        assertionFailure(message)
    }

    /// A missing key returns nil. No symbol substitution, resampling or runtime
    /// SwiftUI rendering occurs. pointSize and scale must match generated keys.
    @MainActor public static func image(set: Set, id: String, pointSize: Double, scale: Double,
                                        appearance: Appearance) -> CGImage? {
        let key = key(set: set, id: id, pointSize: pointSize, scale: scale, appearance: appearance)
        if let image = cache[key] { return image }
        guard let manifest, let directory = resourceDirectory else { return nil }
        guard let entry = manifest.entries[key] else {
            // Not a generated key: catalogue drift, which the tests catch.
            if reportedMissingKeys.insert(key).inserted {
                logger.error("No bundled glyph mask for \(key, privacy: .public)")
            }
            return nil
        }
        guard let source = CGImageSourceCreateWithURL(directory.appendingPathComponent(entry.file) as CFURL, nil),
              let encoded = CGImageSourceCreateImageAtIndex(source, 0, [kCGImageSourceShouldCache: false] as CFDictionary),
              let image = decode(encoded, entry: entry) else {
            reportUnavailable("The bundled glyph mask \(entry.file) for \(key) cannot be loaded.")
            return nil
        }
        cache[key] = image
        return image
    }

    static func decode(_ encoded: CGImage, entry: Entry) -> CGImage? {
        guard entry.format == "rgba", encoded.width == entry.width, encoded.height == entry.height,
              encoded.bitsPerComponent == 8,
              let context = CGContext(data: nil, width: entry.width, height: entry.height,
                bitsPerComponent: 8, bytesPerRow: entry.width * 4,
                space: CGColorSpace(name: CGColorSpace.sRGB)!,
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue | CGBitmapInfo.byteOrder32Big.rawValue)
        else { return nil }
        context.setBlendMode(.copy)
        context.interpolationQuality = .none
        context.draw(encoded, in: CGRect(x: 0, y: 0, width: entry.width, height: entry.height))
        return context.makeImage()
    }

    static func symbolInkSize(_ name: String, pointSize: Double) -> CGSize? {
        guard let size = manifest?.symbolInkSizes["\(name)|\(String(pointSize.bitPattern, radix: 16))"], size.count == 2 else { return nil }
        return CGSize(width: size[0], height: size[1])
    }

    @MainActor static var cachedDecodedBytes: Int { cache.bytes }
    @MainActor static func removeCachedImages() { cache = LayoutWheelLiquidImageCache(limit: 1_048_576) }
}
